import{uid,parseTime,clock,mins,replay,stateAt,backup,importBackup,validateDB}from'./engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v10H3Zm6 10v-7h6v7',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M16 4a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-3M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M4 5h16v16H4ZM8 2v6M16 2v6M4 11h16',chart:'M4 20V10M10 20V4M16 20v-7M22 20V7',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 4v16M4 12h16',arrow:'M4 12h16m-6-6 6 6-6 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',edit:'m15 4 5 5M4 20l4-1L21 6l-4-4L4 15Z',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',swap:'M3 7h16m-5-5 5 5-5 5M21 17H5m5-5-5 5 5 5',clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m4 12 5 5L20 6',close:'m6 6 12 12M18 6 6 18',mail:'M3 5h18v14H3Zm0 0 9 8 9-8',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6Zm-5 9 3 3 7-7',file:'M5 2h9l5 5v15H5Zm9 0v6h5M8 12h8M8 16h8',back:'M20 12H4m6-6-6 6 6 6'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"> <path d="${icons[n]||icons.file}"/></svg>`;
const button=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const initials=n=>n.split(/\s+/).filter(Boolean).slice(0,2).map(v=>v[0]).join('').toUpperCase();
const avatar=n=>`<span class="initial">${esc(initials(n))}</span>`;
const emptyDB=()=>({version:1,players:[],teams:[],matches:[],demo:false});
let db,storageError='';try{const raw=localStorage.getItem('controlmin.v1');db=raw?validateDB(JSON.parse(raw)):emptyDB();}catch(e){db=emptyDB();storageError='No se ha podido leer la copia local. No sobrescribiremos tus datos hasta que exportes o restaures una copia.';}
let view='matches',teamId=db.teams[0]?.id,matchId=null,editingEvent=null,selIn=new Set(),selOut=new Set(),eventType='sub',eventPeriod=0,eventTime='',isHalftime=false,draft=null,search='',playerFilter='',profileId=null;
const currentTeam=()=>db.teams.find(t=>t.id===teamId),currentMatch=()=>db.matches.find(m=>m.id===matchId),player=id=>db.players.find(p=>p.id===id),team=id=>db.teams.find(t=>t.id===id);
const pname=id=>player(id)?.name||'Jugador desconocido';
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function persist(){if(storageError)throw Error('Los datos locales están protegidos. Exporta o restaura una copia antes de continuar.');try{localStorage.setItem('controlmin.v1',JSON.stringify(db));}catch(e){throw Error('No se ha podido guardar. El almacenamiento puede estar lleno o bloqueado. Exporta una copia antes de cerrar.');}}
function commit(next){const before=db;db=next;try{persist();}catch(e){db=before;throw e;}}
function mutate(fn){const next=structuredClone(db);fn(next);commit(next);}
function head(title,sub,actions='',eyebrow=''){return`<div class="heading"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function shell(){const active=profileId?'players':view;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-action="nav" data-view="summary"><img src="./icon.svg" alt=""><span><strong>TimeControl</strong><small>por rkoud</small></span></button><nav>${[['summary','home','Resumen'],['roster','users','Plantilla'],['matches','calendar','Partidos'],['players','users','Jugadores'],['reports','chart','Informes']].map(([v,i,n])=>`<button class="nav ${active===v?'active':''}" data-action="nav" data-view="${v}">${icon(i)}${n}</button>`).join('')}</nav><div class="bottom"><button class="nav ${view==='help'?'active':''}" data-action="nav" data-view="help">${icon('help')}Ayuda y guías</button><button class="nav ${view==='settings'?'active':''}" data-action="nav" data-view="settings">${icon('settings')}Datos y copias</button><div class="saved"><span class="dot"></span>Guardado en este dispositivo</div></div></aside><main class="main"><div class="topbar"><span>Tu equipo, cada minuto.</span><div class="top-actions"><span class="switcher-label">Equipo</span><select id="team-select" aria-label="Equipo activo"><option value="">Selecciona un equipo</option>${db.teams.map(t=>`<option value="${t.id}" ${t.id===teamId?'selected':''}>${esc(t.name)}</option>`).join('')}</select><button class="iconbtn" data-action="new-team" aria-label="Añadir equipo">${icon('plus')}</button><button class="avatar" data-action="nav" data-view="help" aria-label="Ayuda y guías">${icon('help')}</button><button class="avatar mobile-only" data-action="nav" data-view="settings" aria-label="Datos y copias">${icon('settings')}</button></div></div>${db.demo?`<div class="demo-banner"><span>Estás explorando con datos ficticios. Puedes probar todas las funciones.</span><button data-action="clear-demo">Empezar con mis datos</button></div>`:''}${storageError?`<div class="error">${esc(storageError)}</div>`:''}<div id="content"></div><div class="footer"><span>TimeControl · Una herramienta de rkoud</span><span>Datos locales. Sin registro.</span></div></main></div>`;renderContent();}
function renderContent(){const content=$('#content');if(!db.teams.length&&!['help','settings'].includes(view)){content.innerHTML=welcome();return;}
 if(profileId){content.innerHTML=profile();return;}
 const pages={summary:summary,roster:roster,matches:()=>matchId?analysis():matches(),reports:report,players:players,help:help,settings:settings,setup:setup};content.innerHTML=(pages[view]||matches)();}
function welcome(){return`<div class="welcome card"><img src="./icon.svg" alt=""><div class="eyebrow">MENOS CUENTAS. MÁS FÚTBOL.</div><h1>Cada jugador.<br>Cada minuto cuenta.</h1><p>Guarda tu plantilla, registra los cambios y descubre cuánto juega cada uno. En todos tus equipos, desde un mismo lugar.</p><div class="actions">${button(icon('plus')+' Crear mi primer equipo','new-team','primary')}${button('Explorar con datos ficticios','demo')}</div><p class="welcome-note">Tu información permanece en este navegador.<br>Exporta una copia para conservarla o cambiar de dispositivo.</p></div>`;}
function summary(){const ms=db.matches.filter(m=>m.teamId===teamId),done=ms.filter(m=>m.finished);return head('Cada minuto cuenta.',`Un vistazo a ${esc(currentTeam()?.name||'tus equipos')}.`,button(icon('plus')+' Preparar partido','prepare','primary'),'Tu espacio de equipo')+`<div class="metrics">${metric(currentTeam()?.members.length||0,'Jugadores en plantilla','users')}${metric(ms.length,'Partidos guardados','calendar')}${metric(done.length,'Partidos finalizados','check')}${metric(done.reduce((s,m)=>s+mins(replay(m).duration),0)+' min','Tiempo de juego registrado','clock')}</div><div class="grid two"><section class="card"><div class="card-head"><h2>Últimos partidos</h2>${button('Ver todos','nav','quiet','data-view="matches"')}</div>${matchCards(ms.slice().reverse().slice(0,4))}</section><aside><section class="card info-card"><div class="info-icon">${icon('users')}</div><h2>Una ficha. Todos sus equipos.</h2><p>Consulta el historial de cada jugador, con sus minutos acumulados y el detalle de cada partido.</p>${button('Ver jugadores '+icon('arrow'),'nav','','data-view="players"')}</section><section class="card info-card space-top"><h2>Una copia, tranquilidad.</h2><p>Los datos se guardan en este navegador. Descarga una copia al terminar de trabajar.</p>${button(icon('download')+' Exportar datos','export-modal')}</section></aside></div>`;}
function metric(value,label,i){return`<div class="card metric"><div class="row"><strong>${esc(value)}</strong>${icon(i)}</div><small>${esc(label)}</small></div>`;}
function roster(){const t=currentTeam();if(!t)return welcome();const members=t.members.filter(m=>pname(m.playerId).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>Number(a.number)-Number(b.number));return head('Plantilla del equipo','Tus jugadores, listos para cada partido.',button(icon('upload')+' Importar','import')+button(icon('plus')+' Añadir jugador','new-player','primary'),'Equipo / Plantilla')+`<div class="card team-banner"><div class="row"><div class="crest">${esc(initials(t.name))}</div><div><h2>${esc(t.name)}</h2><p>${esc(t.category||'Tu equipo')} · Fútbol ${t.format}</p></div></div>${button(icon('edit')+' Editar equipo','edit-team')}</div><div class="grid two"><section class="card"><div class="card-head"><h2>Jugadores <span class="badge green">${t.members.length}</span></h2><input class="search" id="roster-search" value="${esc(search)}" placeholder="Buscar jugador" aria-label="Buscar jugador"></div><div class="table-wrap"><table><thead><tr><th>Dorsal</th><th>Nombre</th><th>Posición</th><th>Acciones</th></tr></thead><tbody>${members.map(m=>`<tr><td><span class="num-chip">${esc(m.number||'—')}</span></td><td><div class="namecell">${avatar(pname(m.playerId))}<button data-action="profile" data-id="${m.playerId}">${esc(pname(m.playerId))}</button></div></td><td class="muted small">${esc(player(m.playerId)?.position||'Sin especificar')}</td><td><button class="iconbtn" data-action="edit-player" data-id="${m.playerId}" aria-label="Editar ${esc(pname(m.playerId))}">${icon('edit')}</button><button class="iconbtn" data-action="remove-member" data-id="${m.playerId}" aria-label="Quitar de este equipo">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>${!members.length?'<div class="empty"><p>Añade jugadores o vincula una ficha existente.</p></div>':''}<div class="note">✓ Cambios guardados automáticamente en este navegador.</div></section><aside><section class="card info-card"><div class="info-icon">${icon('shield')}</div><h2>Tu plantilla se conserva</h2><p>Se reutiliza en todos tus partidos. La convocatoria de cada encuentro no modifica esta lista.</p><hr><h3>¿Quién juega el próximo partido?</h3><p>Elige los convocados y titulares al preparar cada encuentro.</p>${button('Preparar partido '+icon('arrow'),'prepare')}</section><section class="card info-card space-top"><h2>Copia de seguridad</h2><p>Exporta este equipo con sus jugadores y partidos.</p>${button(icon('download')+' Exportar equipo','export-team')}</section></aside></div>`;}
function matches(){return head('Tus partidos','Prepara un encuentro, continúa un análisis o revisa sus minutos.',button(icon('plus')+' Preparar partido','prepare','primary'),'Equipo / Partidos')+matchCards(db.matches.filter(m=>m.teamId===teamId).slice().reverse());}
function matchCards(ms){if(!ms.length)return`<div class="card empty"><h2>El próximo partido empieza aquí.</h2><p>Selecciona tu convocatoria y registra los tiempos de cámara para comenzar.</p>${button('Preparar partido','prepare','primary')}</div>`;return`<div class="match-list">${ms.map(m=>{const d=new Date((m.date||'2026-01-01')+'T12:00:00');return`<article class="card match-card"><div class="datebox">${esc(d.toLocaleDateString('es',{month:'short'}))}<strong>${d.getDate()}</strong></div><div class="details"><h3>${esc(team(m.teamId)?.name)} <span class="muted">vs</span> ${esc(m.opponent)}</h3><p>Fútbol ${m.format} · ${m.periods.length} ${m.periods.length===1?'parte':'partes'} · ${mins(replay(m).duration)} min · ${m.events.length} eventos</p></div><span class="badge ${m.finished?'green':''}">${m.finished?'Finalizado':'En análisis'}</span><div class="actions">${button('Informe','open-report','','data-id="'+m.id+'"')}${button(m.finished?'Revisar':'Continuar '+icon('arrow'),'open-match','primary','data-id="'+m.id+'"')}</div></article>`;}).join('')}</div>`;}
function startDraft(){const t=currentTeam();if(!t)throw Error('Crea un equipo primero.');draft={id:uid(),teamId:t.id,opponent:'',date:new Date().toLocaleDateString('en-CA'),format:t.format,periodCount:2,periods:[{start:'00:00',end:'25:00'},{start:'35:00',end:'60:00'}],roster:t.members.map(m=>({id:m.playerId,name:pname(m.playerId),number:m.number,called:true,starter:false})),events:[],finished:false};view='setup';matchId=null;shell();}
function setup(){if(!draft)return matches();const called=draft.roster.filter(p=>p.called),starters=called.filter(p=>p.starter);return head('Preparar partido','Elige la convocatoria y los titulares sin modificar tu plantilla.',button('Cancelar','nav','quiet','data-view="matches"'),'Nuevo encuentro')+`<form id="setup-form"><div class="card setup-data"><label>Rival<input name="opponent" value="${esc(draft.opponent)}" placeholder="Nombre del rival" required></label><label>Fecha<input name="date" type="date" value="${esc(draft.date)}" required></label><label>Modalidad<select name="format"><option value="7" ${draft.format===7?'selected':''}>Fútbol 7</option><option value="11" ${draft.format===11?'selected':''}>Fútbol 11</option></select></label><label>Duración<select name="periodCount"><option value="2" ${draft.periodCount===2?'selected':''}>Dos partes</option><option value="1" ${draft.periodCount===1?'selected':''}>Una parte · torneo</option></select></label></div><div class="setup-layout"><section class="card"><div class="card-head"><h2>Convocatoria y titulares</h2><div class="actions"><span class="badge green">${called.length} convocados</span><span class="badge ${starters.length===draft.format?'green':'amber'}">${starters.length} de ${draft.format} titulares</span></div></div><div class="table-wrap"><table><thead><tr><th>Convocado</th><th>Jugador</th><th>Dorsal del partido</th><th>Titular</th></tr></thead><tbody>${draft.roster.map(p=>`<tr><td><input type="checkbox" data-draft="called" data-id="${p.id}" ${p.called?'checked':''} aria-label="Convocar a ${esc(p.name)}"></td><td><div class="namecell">${avatar(p.name)}<strong>${esc(p.name)}</strong></div></td><td><input type="text" maxlength="4" style="width:65px" data-draft="number" data-id="${p.id}" value="${esc(p.number)}" aria-label="Dorsal de ${esc(p.name)}"></td><td><input type="checkbox" data-draft="starter" data-id="${p.id}" ${p.starter&&p.called?'checked':''} ${!p.called?'disabled':''} aria-label="Titular ${esc(p.name)}"></td></tr>`).join('')}</tbody></table></div><div class="note">Los no convocados permanecen en la plantilla. Los dorsales de este partido no cambian los del equipo.</div></section><aside><section class="card form-stack"><h2>Tiempos de cámara</h2><p class="hint">Introduce el inicio y fin reales de cada parte, incluido el añadido. Usa minutos:segundos.</p>${draft.periods.slice(0,draft.periodCount).map((p,i)=>`<div class="fields"><label>Inicio ${i+1}.ª<input name="start${i}" value="${esc(p.start)}" placeholder="00:00" required></label><label>Fin ${i+1}.ª<input name="end${i}" value="${esc(p.end)}" placeholder="25:00" required></label></div>`).join('')}<div class="notice">Verás el vídeo en VEO y registrarás aquí los cambios. El descanso no suma minutos.</div><div id="setup-error"></div><button class="btn primary full" type="submit">Comenzar análisis ${icon('arrow')}</button></section></aside></div></form>`;}
function selectedState(m){let t;try{t=parseTime(eventTime||clock(m.periods[eventPeriod]?.start||0));}catch{return{field:[],blocked:[]};}return stateAt(m,eventPeriod,t,editingEvent);}
function analysis(){const m=currentMatch();if(!m){matchId=null;return matches();}const r=replay(m);if(eventPeriod>=m.periods.length)eventPeriod=0;let state;try{state=selectedState(m);}catch(e){state={field:[],blocked:[]};}const field=m.roster.filter(p=>state.field.includes(p.id)),bench=m.roster.filter(p=>!state.field.includes(p.id));
 return head('Análisis del partido',`${esc(team(m.teamId)?.name)} vs ${esc(m.opponent)} · Fútbol ${m.format}`,button('Informe '+icon('arrow'),'open-report','','data-id="'+m.id+'"')+button(m.finished?'Reabrir análisis':'Finalizar partido','finish',m.finished?'':'primary'),'Vídeo · tiempos manuales')+`<div class="card times-card"><h3>Tiempos de cámara</h3><div class="time-fields">${m.periods.map((p,i)=>`<div><span class="label">Inicio ${i+1}.ª</span><strong class="small">${clock(p.start)}</strong></div><div><span class="label">Fin ${i+1}.ª</span><strong class="small">${clock(p.end)}</strong></div>`).join('')}</div><div class="timing-summary"><strong>${mins(r.duration)} min</strong><small>Descanso excluido</small></div><button class="iconbtn" data-action="edit-times" aria-label="Editar tiempos de cámara">${icon('edit')}</button></div><div class="row between no-print" style="margin-bottom:16px"><p class="hint">Consulta VEO en otra ventana. Selecciona el tiempo y después quién sale y quién entra.</p>${m.periods.length===2?button('Cambios en el descanso','halftime','quiet'):''}</div>${m.finished?'<div class="notice space-top" style="margin-bottom:18px">Partido finalizado. Reabre el análisis para modificar los eventos.</div>':''}<div class="grid three"><section class="card"><div class="card-head"><h2>En el campo <span class="badge green">${field.length}</span></h2><span class="small muted">En el instante elegido</span></div><div class="players-grid">${field.map(p=>playerCard(p,'out',m.finished)).join('')||'<p class="hint">Introduce un tiempo válido.</p>'}</div></section><section class="card"><div class="card-head"><h2>Banquillo</h2><span class="badge">${bench.length}</span></div><div class="bench">${bench.map(p=>playerCard(p,'in',m.finished||state.blocked.includes(p.id),state.blocked.includes(p.id))).join('')}</div></section><section class="card"><div class="card-head"><h2>${icon('swap')} ${editingEvent?'Editar evento':'Registrar cambio'}</h2></div><div class="event-form"><div class="event-types">${[['sub','Cambio'],['red','Expulsión'],['injury','Lesión sin cambio']].map(([t,l])=>`<button data-action="event-type" data-type="${t}" class="${eventType===t?'active':''}" ${m.finished?'disabled':''}>${l}</button>`).join('')}</div><label>Parte<select id="event-period" ${m.finished?'disabled':''}>${m.periods.map((p,i)=>`<option value="${i}" ${i===eventPeriod?'selected':''}>${i+1}.ª parte</option>`).join('')}</select></label><label>Tiempo de cámara<input id="event-time" value="${esc(eventTime||clock(m.periods[eventPeriod].start))}" inputmode="decimal" placeholder="18:32" ${m.finished||isHalftime?'disabled':''}></label><div class="summary-selection">${isHalftime?'<span class="badge green">Cambio en el descanso</span>':''}<div class="selection out">↓ Sale: ${[...selOut].map(id=>esc(m.roster.find(p=>p.id===id)?.name)).join(', ')||'selecciona en el campo'}</div>${eventType==='sub'?`<div class="selection">↑ Entra: ${[...selIn].map(id=>esc(m.roster.find(p=>p.id===id)?.name)).join(', ')||'selecciona en el banquillo'}</div>`:'<p class="hint">Salida definitiva. Este jugador no podrá volver a entrar en el partido.</p>'}</div><button class="btn primary full" data-action="save-event" ${m.finished?'disabled':''}>${editingEvent?'Guardar corrección':'Confirmar '+(eventType==='sub'?'cambio':'salida')} ${icon('check')}</button><button class="btn quiet full" data-action="clear-event">${editingEvent?'Cancelar edición':'Limpiar selección'}</button></div></section></div><div class="grid two analysis-bottom"><section class="card"><div class="card-head"><h2>Participación por jugador</h2><span class="badge">Minutos previstos al completar el partido</span></div>${timeline(m,r)}<p class="footnote">Los tramos abiertos llegan al final configurado de cada parte. El informe será definitivo al finalizar el análisis.</p></section><section class="card"><div class="card-head"><h2>Historial de eventos</h2><span class="badge">${r.events.length}</span></div>${eventList(m,r.events)}</section></div>`;
}
function playerCard(p,side,disabled,blocked=false){const selected=(side==='in'?selIn:selOut).has(p.id);return`<button class="player-card ${selected?side:''} ${blocked?'blocked':''}" data-action="select-player" data-id="${p.id}" data-side="${side}" ${disabled?'disabled':''}>${avatar(p.name)}<strong><span class="num">${esc(p.number||'—')}</span>${esc(p.name)}</strong>${selected?`<span class="selected-tag">${side==='in'?'Entra':'Sale'}</span>`:''}${blocked?'<span class="badge red">Baja</span>':''}</button>`;}
function eventList(m,events){return events.length?events.map(e=>`<div class="event-item"><span class="badge ${e.halftime?'green':''}">${e.halftime?'Descanso':clock(e.time)}</span><div class="content">${e.type==='sub'?'<span style="color:var(--green)">↑ '+e.in.map(id=>esc(m.roster.find(p=>p.id===id)?.name)).join(', ')+'</span><br>':''}↓ ${e.out.map(id=>esc(m.roster.find(p=>p.id===id)?.name)).join(', ')}<small>${e.type==='red'?'Expulsión':e.type==='injury'?'Lesión sin cambio':(e.period+1)+'.ª parte'}</small></div>${!m.finished?`<button class="iconbtn" data-action="edit-event" data-id="${e.id}" aria-label="Editar evento ${clock(e.time)}">${icon('edit')}</button><button class="iconbtn" data-action="delete-event" data-id="${e.id}" aria-label="Borrar evento ${clock(e.time)}">${icon('trash')}</button>`:''}</div>`).join(''):'<p class="hint">Los cambios aparecerán aquí. Puedes corregirlos aunque registres otros después.</p>';}
function timeline(m,r){return`<div class="table-wrap"><table class="timeline-table"><colgroup><col class="player-col">${m.periods.map(()=>'<col>').join('')}<col class="total-col"><col class="pct-col"></colgroup><thead><tr><th>Jugador</th>${m.periods.map((p,i)=>`<th>${i+1}.ª parte<div class="timeline-head"><span>0′</span><span>${clock(p.end-p.start)}</span></div></th>`).join('')}<th>Total</th><th>%</th></tr></thead><tbody>${r.rows.slice().sort((a,b)=>Number(a.number)-Number(b.number)).map(row=>`<tr><td class="person"><span class="num-chip">${esc(row.number||'—')}</span> <strong>${esc(row.name)}</strong></td>${m.periods.map((p,i)=>`<td><div class="track">${row.intervals.filter(iv=>iv.period===i).map(iv=>`<span class="segment" style="left:${(iv.start-p.start)/(p.end-p.start)*100}%;width:${(iv.end-iv.start)/(p.end-p.start)*100}%" title="Cámara ${clock(iv.start)}–${clock(iv.end)}"></span>`).join('')}<span class="track-label ${row.parts[i]?'':'track-zero'}">${mins(row.parts[i])} min</span></div></td>`).join('')}<td><strong>${mins(row.total)} min</strong></td><td class="muted">${row.percent}%</td></tr>`).join('')}</tbody></table></div><div class="legend"><span><i></i>En el campo</span><span><i class="off"></i>Fuera del campo</span><span>Descanso excluido</span></div>`;}
function report(){let m=currentMatch();if(!m){const ms=db.matches.filter(m=>m.teamId===teamId);return head('Informes','Selecciona el partido que quieres consultar.','', 'Minutos y participación')+matchCards(ms.slice().reverse());}const r=replay(m),zero=r.rows.filter(p=>!p.total);return`<div class="print-only print-brand">TimeControl · por rkoud.com ${db.demo?' · EJEMPLO FICTICIO':''}</div>`+head('Informe del partido',`${esc(team(m.teamId)?.name)} vs ${esc(m.opponent)} · ${esc(m.date)}`,button(icon('back')+' Volver al partido','open-match','','data-id="'+m.id+'"')+button(icon('download')+' Exportar informe','report-export','primary'),'Informes / Partido')+`<div class="report-meta"><span class="badge ${m.finished?'green':'amber'}">${m.finished?'✓ Partido finalizado':'Informe provisional'}</span><span class="hint">Fútbol ${m.format} · ${m.periods.length} ${m.periods.length===1?'parte':'partes'} · Descanso excluido</span></div><div class="metrics">${metric(mins(r.duration)+' min','Tiempo de juego','clock')}${metric(m.roster.length,'Convocados','users')}${metric(r.rows.length-zero.length,'Con participación','check')}${metric(zero.length,'Sin participación','users')}</div><section class="card report-card"><div class="card-head"><h2>Participación por jugador</h2><span class="badge">Tramos reales · minutos enteros</span></div>${timeline(m,r)}<p class="footnote">Los minutos de cada parte y el total se redondean por separado al minuto más cercano, a partir de los segundos reales. El porcentaje usa la duración real, incluido el añadido. ${!m.finished?'Los tramos abiertos se proyectan hasta el final configurado.':''}</p></section>${zero.length?`<div class="notice warn space-top">Sin participación: ${zero.map(p=>esc(p.name)).join(', ')}.</div>`:''}<div class="report-extras space-top"><p class="hint">Total del equipo: ${mins(r.rows.reduce((s,p)=>s+p.total,0))} minutos. Tiempos de cámara: ${m.periods.map((p,i)=>`${i+1}.ª ${clock(p.start)}–${clock(p.end)}`).join(' · ')}.</p></div><div class="print-only space-top">TimeControl · rkoud.com · ${db.demo?'Datos ficticios. ':''}Informe generado desde los datos guardados en este navegador.</div>`;}
function players(){const filtered=db.players.filter(p=>p.name.toLowerCase().includes(search.toLowerCase()));return head('Jugadores','Una ficha única, con su historial en todos los equipos.','', 'Historial de participación')+`<section class="card"><div class="card-head"><h2>Todos los jugadores <span class="badge green">${db.players.length}</span></h2><input id="player-search" class="search" placeholder="Buscar jugador" value="${esc(search)}" aria-label="Buscar jugador"></div><div class="table-wrap"><table><thead><tr><th>Jugador</th><th>Equipos</th><th>Partidos finalizados</th><th>Minutos acumulados</th><th></th></tr></thead><tbody>${filtered.map(p=>{const rs=db.matches.filter(m=>m.finished&&m.roster.some(r=>r.id===p.id)).map(m=>replay(m).rows.find(r=>r.id===p.id));return`<tr><td><div class="namecell">${avatar(p.name)}<strong>${esc(p.name)}</strong></div></td><td class="muted small">${db.teams.filter(t=>t.members.some(m=>m.playerId===p.id)||db.matches.some(m=>m.teamId===t.id&&m.roster.some(r=>r.id===p.id))).map(t=>esc(t.name)).join(', ')||'Sin equipo'}</td><td>${rs.length}</td><td><strong>${mins(rs.reduce((s,r)=>s+r.total,0))} min</strong></td><td>${button('Ver ficha '+icon('arrow'),'profile','quiet','data-id="'+p.id+'"')}</td></tr>`;}).join('')}</tbody></table></div><div class="note">Los acumulados incluyen solo partidos finalizados y se calculan con los segundos reales.</div></section>`;}
function profile(){const p=player(profileId);if(!p){profileId=null;return players();}const ms=db.matches.filter(m=>m.finished&&m.roster.some(r=>r.id===p.id)&&(!playerFilter||m.teamId===playerFilter)),rs=ms.map(m=>({m,row:replay(m).rows.find(r=>r.id===p.id)})),total=rs.reduce((s,r)=>s+r.row.total,0),possible=ms.reduce((s,m)=>s+replay(m).duration,0);return head(esc(p.name),'Una ficha única. Todos sus minutos.',button('Todos los jugadores','nav','','data-view="players"'),'Jugador / Historial')+`<div class="row" style="margin-bottom:22px"><label>Filtrar por equipo <select id="profile-team"><option value="">Todos los equipos</option>${db.teams.map(t=>`<option value="${t.id}" ${t.id===playerFilter?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><div class="metrics">${metric(mins(total)+' min','Minutos acumulados','clock')}${metric(ms.length,'Convocatorias finalizadas','calendar')}${metric(rs.filter(r=>r.row.total).length,'Partidos con participación','check')}${metric((possible?Math.round(total/possible*100):0)+'%','Del tiempo disponible','chart')}</div><section class="card"><div class="card-head"><h2>Historial de partidos</h2></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Equipo / Rival</th><th>Dorsal</th><th>Minutos</th><th>%</th><th></th></tr></thead><tbody>${rs.slice().reverse().map(({m,row})=>`<tr><td>${esc(m.date)}</td><td><strong>${esc(team(m.teamId)?.name)}</strong><br><span class="muted small">vs ${esc(m.opponent)}</span></td><td>${esc(row.number)}</td><td><strong>${mins(row.total)} min</strong></td><td>${row.percent}%</td><td>${button('Informe','open-report','quiet','data-id="'+m.id+'"')}</td></tr>`).join('')}</tbody></table></div>${!rs.length?'<div class="empty"><p>Aún no hay partidos finalizados para este filtro.</p></div>':''}<div class="note">El total se obtiene sumando los segundos de todos los partidos antes de redondear.</div></section>`;}
function help(){return head('Ayuda y guías','Lo necesario para centrarte en el partido.','', 'A tu lado, desde el primer minuto')+`<div class="help-grid"><article class="card"><h2>01 · Prepara tu equipo</h2><p>Crea un equipo y añade su plantilla. Si un jugador ya existe en otro equipo, vincula su ficha en lugar de crear otra. Puede llevar un dorsal distinto en cada equipo y partido.</p></article><article class="card"><h2>02 · Analiza con VEO</h2><ol><li>Abre VEO en otra ventana.</li><li>Configura los tiempos reales de cámara de una o dos partes.</li><li>Introduce el tiempo del evento y selecciona quién sale y quién entra.</li><li>Confirma uno o varios cambios a la vez.</li></ol></article><article class="card"><h2>03 · Descanso y salidas</h2><p>Si no registras cambios en el descanso, continúan los mismos jugadores. Usa «Cambios en el descanso» para sustituirlos al inicio de la segunda parte. Expulsión y lesión sin cambio son salidas definitivas; no permiten regresar.</p></article><article class="card"><h2>04 · Corrige e informa</h2><p>Puedes corregir o borrar cualquier evento. El historial se recalcula cronológicamente; si una corrección hace incoherente otro evento, se explica el conflicto antes de guardar. Reabre un partido finalizado para corregirlo.</p></article><article class="card"><h2>05 · Entiende los minutos</h2><p>Se conservan los segundos. Cada parte y el total se redondean de forma independiente al minuto más cercano. El porcentaje se calcula con los segundos reales. Antes de finalizar el análisis, los intervalos abiertos son minutos previstos.</p></article><article class="card"><h2>06 · Conserva tus datos</h2><p>Los datos pertenecen a este navegador y dirección web. No se sincronizan entre dispositivos. Exporta todos los equipos, un equipo o un partido. Al importar se sustituye el ámbito elegido; antes se guarda una copia local de recuperación.</p></article><article class="card"><h2>Vídeos de guía</h2><p>Prepararemos las guías en vídeo cuando el flujo de la aplicación esté validado. Mientras tanto, estas instrucciones están disponibles en cualquier momento.</p></article><article class="card"><h2>PDF y correo</h2><p>En el informe elige PDF y usa «Guardar como PDF» en la impresión del navegador. Para enviar una copia por correo, descárgala y adjúntala manualmente. Si tu navegador permite compartir archivos, puedes usar el botón Compartir.</p></article></div>`;}
function settings(){return head('Tus datos, a salvo.','Copias completas o por equipo y partido. Tú decides.','', 'Datos y copias')+`<div class="grid two"><section class="card info-card"><div class="info-icon">${icon('download')}</div><h2>Exportar e importar</h2><p>Descarga un archivo JSON para guardar tus datos o enviarlo por correo. La copia incluye las fichas necesarias para conservar el historial.</p><div class="actions">${button(icon('download')+' Exportar copia','export-modal','primary')}${button(icon('mail')+' Exportar por correo','email-modal')}${button(icon('upload')+' Importar copia','import')}</div><hr><h3>Al importar</h3><p>La copia importada sustituye los datos del ámbito elegido. Los otros equipos o partidos se conservan. Las fichas de jugador compartidas se actualizan con los datos de la copia.</p>${button('Descargar copia previa a la última importación','recovery')}</section><aside><section class="card info-card"><h2>Guardado en este navegador</h2><p>Sin cuentas ni servidor de datos. Borrar el almacenamiento del navegador elimina la información local. Una copia exportada permite recuperarla.</p><p>La fecha de la copia se muestra antes de importarla. Para conservar la última, importa el archivo más reciente.</p></section><section class="card info-card space-top"><h2>Reiniciar aplicación</h2><p>Elimina los datos de este navegador. Exporta antes una copia si quieres conservarlos.</p>${button('Borrar todos los datos','reset','danger')}</section></aside></div>`;}
function modal(title,body,onSubmit){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="iconbtn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><form id="modal-form"><div class="modal-body">${body}</div><div id="modal-error"></div>${onSubmit?'<div class="form-footer"><button type="button" class="btn quiet" data-action="close-modal">Cancelar</button><button type="submit" class="btn primary">Guardar</button></div>':''}</form>`;if(!d.open)d.showModal();$('#modal-form').onsubmit=e=>{e.preventDefault();try{onSubmit?.(new FormData(e.target));}catch(e){$('#modal-error').innerHTML=`<div class="error">${esc(e.message)}</div>`;}};}
function closeModal(){$('#modal').close();}
function confirmAction(title,desc,fn,label='Confirmar'){modal(title,`<p>${desc}</p><div class="form-footer"><button type="button" class="btn quiet" data-action="close-modal">Cancelar</button><button type="button" id="confirm-action" class="btn primary">${esc(label)}</button></div>`);$('#confirm-action').onclick=()=>{try{fn();closeModal();shell();}catch(e){$('#modal-error').innerHTML=`<div class="error">${esc(e.message)}</div>`;}};}
function teamModal(edit=false){const t=edit?currentTeam():null;modal(edit?'Editar equipo':'Nuevo equipo',`<div class="fields"><label class="field-full">Nombre del equipo<input name="name" value="${esc(t?.name||'')}" required maxlength="80" placeholder="Ej. CD Norte"></label><label>Categoría<input name="category" value="${esc(t?.category||'')}" maxlength="60" placeholder="Ej. Alevín A"></label><label>Modalidad<select name="format"><option value="7" ${t?.format===7?'selected':''}>Fútbol 7</option><option value="11" ${t?.format===11?'selected':''}>Fútbol 11</option></select></label></div>`,fd=>{const name=fd.get('name').trim();if(!name)throw Error('Introduce un nombre.');const id=t?.id||uid();mutate(d=>{if(t)Object.assign(d.teams.find(x=>x.id===id),{name,category:fd.get('category').trim(),format:+fd.get('format')});else d.teams.push({id,name,category:fd.get('category').trim(),format:+fd.get('format'),members:[]});});teamId=id;view='roster';profileId=null;matchId=null;closeModal();shell();toast('Equipo guardado');});}
function playerModal(id){const p=id?player(id):null,t=currentTeam(),member=t.members.find(m=>m.playerId===id),existing=db.players.filter(p=>!t.members.some(m=>m.playerId===p.id));modal(p?'Editar jugador':'Añadir jugador',`<div class="form-stack">${!p&&existing.length?`<label>Vincular una ficha existente<select name="existing" id="existing-player"><option value="">Crear una nueva ficha</option>${existing.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><p class="hint">Si juega en otro equipo, vincula su ficha para sumar todo su historial.</p>`:''}<label>Nombre<input name="name" id="new-player-name" value="${esc(p?.name||'')}" ${p||!existing.length?'required':''} maxlength="80" placeholder="Nombre del jugador"></label><div class="fields"><label>Dorsal en este equipo<input name="number" value="${esc(member?.number||'')}" maxlength="4"></label><label>Posición (opcional)<select name="position">${['','Portero','Defensa','Centrocampista','Delantero'].map(pos=>`<option ${pos===p?.position?'selected':''}>${pos}</option>`).join('')}</select></label></div>${p?'<p class="hint">El nombre y la posición pertenecen a su ficha única. El dorsal cambia solo en este equipo. Los partidos ya creados conservan sus datos históricos.</p>':''}</div>`,fd=>{let pid=p?.id||fd.get('existing')||uid(),name=String(fd.get('name')||'').trim(),position=fd.get('position');const linked=!!fd.get('existing');if(!linked&&!name)throw Error('Introduce el nombre del jugador.');if(!p&&!linked&&db.players.some(p=>p.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw Error('Ya hay una ficha con ese nombre. Vincúlala desde la lista o usa un nombre que permita distinguirlos.');mutate(d=>{if(p)Object.assign(d.players.find(x=>x.id===pid),{name,position});else if(!linked)d.players.push({id:pid,name,position});const members=d.teams.find(x=>x.id===t.id).members;if(p)members.find(m=>m.playerId===pid).number=fd.get('number').trim();else members.push({playerId:pid,number:fd.get('number').trim()});});closeModal();shell();toast('Jugador guardado');});}
function resetEvent(m=currentMatch()){editingEvent=null;selIn.clear();selOut.clear();eventType='sub';isHalftime=false;eventPeriod=0;eventTime=m?clock(m.periods[0].start):'';}
function saveEvent(){const m=currentMatch();if(m.finished)throw Error('Reabre el análisis para registrar cambios.');const time=isHalftime?m.periods[1].start:parseTime(eventTime||clock(m.periods[eventPeriod].start));const e={id:editingEvent||uid(),order:editingEvent?m.events.find(e=>e.id===editingEvent).order:Math.max(0,...m.events.map(e=>e.order||0))+1,type:eventType,period:eventPeriod,time,in:eventType==='sub'?[...selIn]:[],out:[...selOut],halftime:isHalftime};const next=structuredClone(m);next.events=next.events.filter(x=>x.id!==e.id).concat(e);replay(next);mutate(d=>d.matches[d.matches.findIndex(x=>x.id===m.id)]=next);const keepTime=clock(time),keepPeriod=eventPeriod;resetEvent();eventTime=keepTime;eventPeriod=keepPeriod;shell();toast('Evento guardado. Minutos recalculados.');}
function editTimes(){const m=currentMatch();modal('Tiempos reales de cámara',`<div class="form-stack"><p class="hint">Incluye el tiempo añadido. Los cambios de descanso se desplazarán al nuevo inicio de la segunda parte; el resto conserva sus tiempos de cámara.</p>${m.periods.map((p,i)=>`<div class="fields"><label>Inicio ${i+1}.ª<input name="start${i}" value="${clock(p.start)}" required></label><label>Fin ${i+1}.ª<input name="end${i}" value="${clock(p.end)}" required></label></div>`).join('')}</div>`,fd=>{if(m.finished)throw Error('Reabre el análisis antes de cambiar los tiempos.');const next=structuredClone(m);next.periods=next.periods.map((p,i)=>({start:parseTime(fd.get('start'+i)),end:parseTime(fd.get('end'+i))}));next.events.forEach(e=>{if(e.halftime)e.time=next.periods[1].start;});replay(next);mutate(d=>d.matches[d.matches.findIndex(x=>x.id===m.id)]=next);resetEvent(next);closeModal();shell();toast('Tiempos actualizados');});}
function download(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);return blob;}
function exportModal(email=false,scope='all'){modal(email?'Exportar por correo':'Exportar copia',`<div class="form-stack"><label>Qué quieres exportar<select id="export-scope"><option value="all" ${scope==='all'?'selected':''}>Todos los equipos</option><option value="team" ${scope==='team'?'selected':''}>Un equipo</option><option value="match" ${scope==='match'?'selected':''}>Un partido</option></select></label><label>Equipo<select id="export-team">${db.teams.map(t=>`<option value="${t.id}" ${t.id===teamId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Partido<select id="export-match">${db.matches.map(m=>`<option value="${m.id}" ${m.id===matchId?'selected':''}>${esc(team(m.teamId)?.name)} vs ${esc(m.opponent)} · ${esc(m.date)}</option>`).join('')}</select></label><p class="hint">La copia contiene los jugadores y los datos necesarios del ámbito elegido. Al importarla se sustituirá ese ámbito.</p>${email?'<div class="notice">Se descargará el archivo y se abrirá tu aplicación de correo. Adjunta el archivo descargado antes de enviarlo.</div>':''}<div class="actions">${button(icon('download')+(email?' Descargar y abrir correo':' Descargar JSON'),'do-export','primary',`data-email="${email?'yes':'no'}"`)}${button('Compartir archivo','share-export')}</div></div>`);}
function exportPacket(){const scope=$('#export-scope').value,id=scope==='team'?$('#export-team').value:scope==='match'?$('#export-match').value:null;if(scope!=='all'&&!id)throw Error('No hay datos disponibles para este ámbito.');return backup(db,scope,id);}
function reportExport(){modal('Exportar informe',`<div class="export-options">${button(icon('file')+' PDF · imprimir o guardar','print-report')}${button(icon('download')+' CSV para Excel','csv-report')}${button(icon('file')+' Copiar resumen','copy-report')}${button(icon('download')+' Copia JSON del partido','export-match')}</div><p class="hint space-top">Para crear el PDF, elige «Guardar como PDF» en el diálogo de impresión. Usa orientación horizontal.</p>`);}
function reportText(m){const r=replay(m);return`${team(m.teamId)?.name} vs ${m.opponent}\n${m.date} · ${mins(r.duration)} minutos\n\n`+r.rows.map(p=>`${p.number||'—'} ${p.name}: ${p.parts.map(mins).join(' + ')} min · Total ${mins(p.total)} min · ${p.percent}%`).join('\n');}
function csvReport(){const m=currentMatch(),r=replay(m);const cell=v=>{let s=String(v);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"';};let rows=[['Dorsal','Jugador',...m.periods.map((_,i)=>`Min_${i+1}a`),'Total_min','Porcentaje','Total_segundos'],...r.rows.map(p=>[p.number,p.name,...p.parts.map(mins),mins(p.total),p.percent,p.total])];download('timecontrol-informe.csv','\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function importFile(file){const reader=new FileReader();reader.onload=()=>{try{const packet=JSON.parse(reader.result);const next=importBackup(db,packet);const date=new Date(packet.exportedAt);if(Number.isNaN(date.getTime()))throw Error('La copia no tiene una fecha válida.');confirmAction('Importar copia',`Copia del <strong>${esc(date.toLocaleString('es'))}</strong>.<br>Ámbito: <strong>${esc({all:'todos los equipos',team:'un equipo',match:'un partido'}[packet.scope])}</strong>.<br><br>Se sustituirán los datos de ese ámbito. Los datos de los jugadores compartidos se actualizarán. Se guardará una copia local de recuperación antes de importar.`,()=>{localStorage.setItem('controlmin.recovery',JSON.stringify(backup(db,'all')));storageError='';commit(next);teamId=db.teams[0]?.id;matchId=null;profileId=null;view='matches';toast('Copia importada');},'Sustituir con esta copia');}catch(e){toast(e.message);}};reader.onerror=()=>toast('No se pudo leer el archivo.');reader.readAsText(file);}
function loadDemo(){const names=['Hugo M.','Lucas R.','Mateo G.','Leo S.','Martín P.','Pablo D.','Dani L.','Álex C.','Bruno V.','Nico A.','Iker T.','Mario F.'];const nums=[1,3,4,6,7,9,11,12,14,15,16,18];const ps=names.map((name,i)=>({id:uid(),name,position:i===0||i===11?'Portero':i<4?'Defensa':i<8?'Centrocampista':'Delantero'}));const tid=uid(),tid2=uid(),mid=uid();const roster=ps.map((p,i)=>({id:p.id,name:p.name,number:String(nums[i])}));const event=(time,out,ins,period=0,halftime=false)=>({id:uid(),type:'sub',time,period,halftime,out:out.map(i=>ps[i].id),in:ins.map(i=>ps[i].id),order:time});const m={id:mid,teamId:tid,opponent:'UD Central',date:'2026-11-15',format:7,roster,starters:ps.slice(0,7).map(p=>p.id),periods:[{start:200,end:1700},{start:2300,end:3800}],finished:false,events:[event(800,[6],[7]),event(1100,[4],[9]),event(2300,[2,5,9],[8,10,4],1,true),event(2900,[1],[5],1),event(3200,[4],[6],1),event(3500,[8],[9],1)]};replay(m);const next={version:1,demo:true,players:ps,teams:[{id:tid,name:'CD Norte',category:'Alevín A',format:7,members:ps.map((p,i)=>({playerId:p.id,number:String(nums[i])}))},{id:tid2,name:'Escuela Norte',category:'Grupo de tecnificación',format:7,members:ps.slice(0,9).map((p,i)=>({playerId:p.id,number:String(i+10)}))}],matches:[m]};commit(next);teamId=tid;matchId=mid;view='matches';resetEvent(m);eventTime='18:20';shell();}
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 try{switch(a){
 case'nav':view=b.dataset.view;profileId=null;search='';matchId=null;draft=null;shell();break;
 case'new-team':teamModal();break;case'edit-team':teamModal(true);break;
 case'new-player':playerModal();break;case'edit-player':playerModal(id);break;
 case'remove-member':confirmAction('Quitar de este equipo',`¿Quitar a <strong>${esc(pname(id))}</strong> de la plantilla? Su ficha y sus partidos anteriores se conservan.`,()=>mutate(d=>d.teams.find(t=>t.id===teamId).members=d.teams.find(t=>t.id===teamId).members.filter(m=>m.playerId!==id)));break;
 case'profile':profileId=id;playerFilter='';shell();break;
 case'prepare':startDraft();break;
 case'open-match':matchId=id;teamId=currentMatch().teamId;profileId=null;view='matches';resetEvent();shell();break;
 case'open-report':matchId=id;teamId=currentMatch().teamId;profileId=null;view='reports';shell();break;
 case'event-type':eventType=b.dataset.type;selIn.clear();selOut.clear();if(eventType!=='sub')isHalftime=false;shell();break;
 case'select-player':{const m=currentMatch();if(m.finished)break;if(b.dataset.side==='in'){if(eventType!=='sub')throw Error('Expulsión y lesión sin cambio no admiten un sustituto.');if(selIn.has(id))selIn.delete(id);else selIn.add(id);}else{if(selOut.has(id))selOut.delete(id);else{if(eventType!=='sub')selOut.clear();selOut.add(id);}}shell();break;}
 case'halftime':if(currentMatch().finished)throw Error('Reabre el análisis para modificarlo.');resetEvent();eventPeriod=1;eventTime=clock(currentMatch().periods[1].start);isHalftime=true;shell();break;
 case'clear-event':resetEvent();shell();break;
 case'save-event':saveEvent();break;
 case'edit-times':editTimes();break;
 case'finish':{const m=currentMatch();confirmAction(m.finished?'Reabrir análisis':'Finalizar partido',m.finished?'Podrás corregir los eventos y los tiempos. El partido dejará de contar en los acumulados hasta que lo finalices otra vez.':'Comprueba que los tiempos de fin incluyen el añadido y que has registrado todos los cambios. El informe y el historial del jugador usarán estos datos.',()=>{mutate(d=>d.matches.find(x=>x.id===m.id).finished=!m.finished);if(!m.finished)view='reports';resetEvent();});break;}
 case'edit-event':{const e=currentMatch().events.find(x=>x.id===id);editingEvent=id;eventType=e.type;eventPeriod=e.period;eventTime=clock(e.time);isHalftime=!!e.halftime;selIn=new Set(e.in);selOut=new Set(e.out);shell();window.scrollTo({top:0,behavior:'smooth'});break;}
 case'delete-event':confirmAction('Borrar evento','Los minutos se recalcularán. Si otro evento depende de este cambio, se avisará antes de guardar.',()=>{const m=structuredClone(currentMatch());m.events=m.events.filter(e=>e.id!==id);replay(m);mutate(d=>d.matches[d.matches.findIndex(x=>x.id===m.id)]=m);resetEvent(m);});break;
 case'close-modal':closeModal();break;
 case'export-modal':exportModal();break;case'email-modal':exportModal(true);break;case'export-team':exportModal(false,'team');break;case'export-match':exportModal(false,'match');break;
 case'do-export':{const packet=exportPacket(),name=`timecontrol-${packet.scope}-${new Date().toISOString().slice(0,10)}.json`;download(name,JSON.stringify(packet,null,2));if(b.dataset.email==='yes')window.location.href='mailto:?subject='+encodeURIComponent('Copia de TimeControl')+'&body='+encodeURIComponent('Adjunto mi copia de TimeControl.\n\nRecuerda adjuntar el archivo '+name+' que se acaba de descargar.');toast('Copia descargada'+(b.dataset.email==='yes'?'. Adjunta el archivo en tu correo.':''));break;}
 case'share-export':{const packet=exportPacket(),file=new File([JSON.stringify(packet,null,2)],'timecontrol-copia.json',{type:'application/json'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Copia de TimeControl'});}catch(e){if(e.name!=='AbortError')throw e;}}else toast('Este navegador no comparte archivos. Descarga la copia y adjúntala en tu correo.');break;}
 case'import':$('#import-file').value='';$('#import-file').click();break;
 case'recovery':{const raw=localStorage.getItem('controlmin.recovery');if(!raw)throw Error('Todavía no hay una copia previa a una importación.');download('timecontrol-recuperacion.json',raw);break;}
 case'report-export':reportExport();break;
 case'print-report':closeModal();window.print();break;
 case'csv-report':csvReport();toast('CSV descargado');break;
 case'copy-report':await navigator.clipboard.writeText(reportText(currentMatch()));toast('Resumen copiado');break;
 case'demo':loadDemo();break;
 case'clear-demo':case'reset':confirmAction('Empezar de nuevo','Se borrarán todos los equipos, jugadores y partidos de este navegador. Exporta antes una copia si quieres conservarlos.',()=>{storageError='';commit(emptyDB());teamId=null;matchId=null;profileId=null;view='matches';});break;
 }
 }catch(e){toast(e.message);}
});
document.addEventListener('change',ev=>{const el=ev.target;try{
 if(el.id==='team-select'){teamId=el.value;matchId=null;profileId=null;draft=null;view='matches';shell();}
 if(el.id==='event-period'){eventPeriod=+el.value;eventTime=clock(currentMatch().periods[eventPeriod].start);selIn.clear();selOut.clear();isHalftime=false;shell();}
 if(el.id==='event-time'){eventTime=el.value;const time=parseTime(eventTime);const m=currentMatch();const found=m.periods.findIndex(p=>time>=p.start&&time<=p.end);if(found>=0)eventPeriod=found;else throw Error('El tiempo debe estar dentro de una parte. Para cambios de descanso usa su botón.');selIn.clear();selOut.clear();isHalftime=false;shell();}
 if(el.id==='profile-team'){playerFilter=el.value;shell();}
 if(el.id==='existing-player'){const name=$('#new-player-name');name.disabled=!!el.value;name.required=!el.value;}
 if(el.id==='import-file'&&el.files[0]){if(el.files[0].size>10*1024*1024)throw Error('La copia es demasiado grande (máximo 10 MB).');importFile(el.files[0]);}
 if(el.dataset.draft){syncDraft();const p=draft.roster.find(p=>p.id===el.dataset.id);const key=el.dataset.draft;p[key]=key==='number'?el.value:el.checked;if(key==='called'&&!p.called)p.starter=false;if(key!=='number')shell();}
 if(el.closest('#setup-form')&&['periodCount','format'].includes(el.name)){syncDraft();shell();}
 }catch(e){toast(e.message);}
});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='event-time')eventTime=el.value;if(['roster-search','player-search'].includes(el.id)){const pos=el.selectionStart;search=el.value;renderContent();const n=$('#'+el.id);n.focus();n.setSelectionRange(pos,pos);}});
function syncDraft(){const f=$('#setup-form');if(!f||!draft)return;draft.opponent=f.elements.opponent.value;draft.date=f.elements.date.value;draft.format=+f.elements.format.value;draft.periodCount=+f.elements.periodCount.value;for(let i=0;i<2;i++){if(f.elements['start'+i])draft.periods[i]={start:f.elements['start'+i].value,end:f.elements['end'+i].value};}}
document.addEventListener('submit',ev=>{if(ev.target.id!=='setup-form')return;ev.preventDefault();try{syncDraft();const m={id:draft.id,teamId:draft.teamId,opponent:draft.opponent.trim(),date:draft.date,format:draft.format,periods:draft.periods.slice(0,draft.periodCount).map(p=>({start:parseTime(p.start),end:parseTime(p.end)})),roster:draft.roster.filter(p=>p.called).map(({id,name,number})=>({id,name,number})),starters:draft.roster.filter(p=>p.called&&p.starter).map(p=>p.id),events:[],finished:false};if(!m.date)throw Error('Selecciona una fecha.');replay(m);mutate(d=>d.matches.push(m));matchId=m.id;view='matches';draft=null;resetEvent(m);shell();toast('Partido preparado');}catch(e){$('#setup-error').innerHTML=`<div class="error">${esc(e.message)}</div>`;}});
window.addEventListener('storage',ev=>{if(ev.key==='controlmin.v1'){storageError='Los datos han cambiado en otra pestaña. Recarga esta página antes de guardar para evitar sobrescribirlos.';shell();}});
shell();

if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
